mapper.select:
SELECT SUBSCRIPTION_BILLING_KEY_ID
FROM SUBSCRIPTION_BILLING_KEY
WHERE MEMBER_ID = #{memberId}

mapper.update:
UPDATE SUBSCRIPTIONS
SET BILLINGKEY_ID = #{billingKeyId}
WHERE SUBSCRIPTION_ID = #{subscriptionId}
  AND STATUS = 'PENDING'
  AND BILLINGKEY_ID IS NULL

UPDATE SUBSCRIPTION_PAYMENT_HISTORIES
SET BILLINGKEY_ID = #{billingKeyId}
WHERE HISTORY_ID = #{historyId}
  AND STATUS = 'READY'
  AND BILLINGKEY_ID IS NULL

UPDATE SUBSCRIPTION_PAYMENT_HISTORIES
SET
    STATUS = 'FAILED',
    FAIL_REASON = #{failReason}
WHERE HISTORY_ID = #{historyId}
  AND STATUS = 'READY'

UPDATE SUBSCRIPTION_PAYMENT_HISTORIES
SET PORTONE_SCHEDULE_ID = #{portoneScheduleId}
WHERE HISTORY_ID = #{historyId}
  AND STATUS = 'READY'

UPDATE SUBSCRIPTION_APPLICATIONS
SET STATUS = 'CANCELED',
    CANCELED_AT = CURRENT_TIMESTAMP,
    FAIL_REASON = #{failReason}
WHERE APPLICATION_ID = #{applicationId}
  AND STATUS = 'PENDING'

UPDATE SUBSCRIPTION_APPLICATIONS
SET STATUS = 'FAILED',
    FAILED_AT = CURRENT_TIMESTAMP,
    FAIL_REASON = #{failReason}
WHERE APPLICATION_ID = #{applicationId}
  AND STATUS = 'PENDING'

UPDATE SUBSCRIPTION_PAYMENT_HISTORIES
SET STATUS = 'CANCELED',
    FAIL_REASON = #{failReason}
WHERE HISTORY_ID = #{historyId}
  AND STATUS = 'READY'
